// Endpoint-Übersicht HTML-Generator
// baramundi come2gether 2026 Challenge
//
// Quelle: plattform-typisierte Endpoint-Operationen (Windows/Linux/Mac),
// zusammengeführt in EINEM Merge-Node (3 Eingänge).
// Zur Sicherheit wird hier zusätzlich nach Endpoint-ID dedupliziert,
// damit der Report garantiert keine Duplikate enthält.

const items = $input.all();

// --- Deduplizieren nach eindeutiger Endpoint-ID ---
const seen = new Set();
const unique = [];
for (const item of items) {
  const ep = item.json || {};
  const key = ep.id || ep.endpointId || (ep.hostName + '|' + ep.endpointType);
  if (seen.has(key)) continue;
  seen.add(key);
  unique.push(ep);
}

const duplicatesRemoved = items.length - unique.length;

const data = unique.map(ep => ({
  displayName: ep.displayName || ep.hostName || 'Unbekannt',
  type: (ep.endpointType || 'Unbekannt').replace('Endpoint', ''),
  os: ep.operatingSystem || 'Unbekannt',
  lastSeen: ep.lastSeen || 'Nie',
  ip: ep.primaryIP || ep.primaryIpAddress || ep.primaryMAC || '-',
  user: ep.primaryUser || '-',
  domain: ep.domain || '-'
}));

// Zähler pro Plattform
const typeCounts = {};
data.forEach(ep => { typeCounts[ep.type] = (typeCounts[ep.type] || 0) + 1; });

// Plattform-Farben
const typeColors = {
  'Windows': { bg: '#e3f2fd', border: '#1976d2', icon: '<span style="display:inline-grid;grid-template-columns:6px 6px;gap:1.5px;vertical-align:-2px;margin-right:5px;"><span style="width:6px;height:6px;background:#0078D4;"></span><span style="width:6px;height:6px;background:#0078D4;"></span><span style="width:6px;height:6px;background:#0078D4;"></span><span style="width:6px;height:6px;background:#0078D4;"></span></span>' },
  'Linux':   { bg: '#fff3e0', border: '#f57c00', icon: '\uD83D\uDC27' },
  'Mac':     { bg: '#f5f5f5', border: '#757575', icon: '<span style="position:relative;display:inline-block;width:13px;height:15px;vertical-align:-3px;margin-right:5px;"><span style="position:absolute;left:0;bottom:0;width:13px;height:11px;background:#555;border-radius:50% 50% 47% 47%/58% 58% 42% 42%;"></span><span style="position:absolute;right:-1px;top:6px;width:5px;height:6px;background:#f5f5f5;border-radius:50%;"></span><span style="position:absolute;top:0;right:3px;width:5px;height:5px;background:#555;border-radius:0 60% 0 60%;transform:rotate(20deg);"></span></span>' },
  'Android': { bg: '#e8f5e9', border: '#4caf50', icon: '\uD83E\uDD16' },
  'iOS':     { bg: '#e1f5fe', border: '#03a9f4', icon: '\uD83D\uDCF1' },
  'Network': { bg: '#f3e5f5', border: '#9c27b0', icon: '\uD83C\uDF10' }
};

const now = new Date().toLocaleString('de-DE', {
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit'
});

// Kacheln
const tiles = Object.entries(typeCounts).map(([type, count]) => {
  const c = typeColors[type] || { bg: '#eceff1', border: '#90a4ae', icon: '\uD83D\uDCBB' };
  return `<div style="background:${c.bg};border-left:4px solid ${c.border};padding:16px 20px;border-radius:6px;min-width:120px;">
    <div style="font-size:28px;font-weight:700;color:${c.border};">${count}</div>
    <div style="font-size:13px;color:#555;margin-top:4px;">${type}</div>
  </div>`;
}).join('');

// Tabellenzeilen
const rows = data.map(ep => {
  const c = typeColors[ep.type] || { bg: '#eceff1', border: '#90a4ae' };
  return `<tr>
    <td style="font-weight:500;">${ep.displayName}</td>
    <td><span style="background:${c.bg};color:${c.border};padding:3px 10px;border-radius:4px;font-size:12px;font-weight:600;">${ep.type}</span></td>
    <td>${ep.os}</td>
    <td><code style="background:#f5f5f5;padding:2px 6px;border-radius:3px;font-size:13px;">${ep.ip}</code></td>
    <td>${ep.user}</td>
    <td style="font-size:13px;color:#666;">${ep.lastSeen}</td>
  </tr>`;
}).join('');

const dupNote = duplicatesRemoved > 0
  ? `<span style="color:#c62828;">${duplicatesRemoved} Duplikate entfernt</span>`
  : `<span style="color:#2e7d32;">keine Duplikate</span>`;

const html = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8">
  <title>Endpoint-Übersicht - baramundi</title>
  <style>
    * { margin:0; padding:0; box-sizing:border-box; }
    body { font-family:'Segoe UI',Arial,sans-serif; background:#f0f2f5; padding:24px; }
    .container { max-width:1400px; margin:0 auto; background:#fff; border-radius:10px; box-shadow:0 2px 12px rgba(0,0,0,0.08); overflow:hidden; }
    .header { background:linear-gradient(135deg,#003c71 0%,#00a3e0 100%); color:#fff; padding:28px 36px; }
    .header h1 { font-size:24px; font-weight:700; }
    .header .sub { font-size:13px; opacity:0.9; margin-top:4px; }
    .tiles { display:flex; gap:16px; flex-wrap:wrap; padding:24px 36px; background:#fafbfc; border-bottom:1px solid #e9ecef; }
    .total { background:#003c71; color:#fff; padding:16px 20px; border-radius:6px; min-width:120px; }
    .total .num { font-size:28px; font-weight:700; }
    .total .lbl { font-size:13px; opacity:0.85; margin-top:4px; }
    table { width:100%; border-collapse:collapse; font-size:14px; }
    thead tr { background:#003c71; color:#fff; }
    th { padding:12px 16px; text-align:left; font-size:12px; text-transform:uppercase; letter-spacing:0.5px; font-weight:600; }
    td { padding:10px 16px; border-bottom:1px solid #e9ecef; }
    tbody tr:hover { background:#f8f9fa; }
    .footer { background:#fafbfc; padding:14px 36px; border-top:1px solid #e9ecef; font-size:12px; color:#888; text-align:center; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>Endpoint-Übersicht</h1>
      <div class="sub">baramundi Management Suite &mdash; Generiert: ${now} &mdash; ${dupNote}</div>
    </div>
    <div class="tiles">
      <div class="total"><div class="num">${data.length}</div><div class="lbl">Gesamt (eindeutig)</div></div>
      ${tiles}
    </div>
    <div style="padding:0 36px 36px;overflow-x:auto;">
      <table>
        <thead><tr><th>Hostname</th><th>Plattform</th><th>Betriebssystem</th><th>IP / MAC</th><th>Benutzer</th><th>Zuletzt gesehen</th></tr></thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <div class="footer">baramundi come2gether 2026 Challenge &mdash; Workflow 01: Endpoint-Übersicht &mdash; ${data.length} eindeutige Endpoints</div>
  </div>
</body>
</html>`;

return { json: { html, totalUnique: data.length, duplicatesRemoved, byPlatform: typeCounts } };
